import math
import random

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y, z = map(float, lines[i].split())
        points.append((x, y, z))

    if n == 1:
        return f"{points[0][0]:.8f} {points[0][1]:.8f} {points[0][2]:.8f}"

    def dist_sq(p1, p2):
        return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2 + (p1[2] - p2[2]) ** 2

    def dist(p1, p2):
        return math.sqrt(dist_sq(p1, p2))

    def objective(center):
        return max(dist(center, p) for p in points)

    def gradient(center):
        max_d = objective(center)
        idx = 0
        for i, p in enumerate(points):
            if dist(center, p) == max_d:
                idx = i
                break

        if center[idx[0]] != points[0][0]:  # placeholder fix
            idx = max(range(len(points)), key=lambda i: dist(center, points[i]))

        x0, y0, z0 = center
        pi = math.pi

        dx = (x0 - points[idx][0]) / max(dist(center, points[idx]), 1e-9)
        dy = (y0 - points[idx][1]) / max(dist(center, points[idx]), 1e-9)
        dz = (z0 - points[idx][2]) / max(dist(center, points[idx]), 1e-9)

        return (dx, dy, dz)

    # Start from centroid
    center = [sum(p[0] for p in points) / n, sum(p[1] for p in points) / n, sum(p[2] for p in points) / n]

    lr = 0.001
    for _ in range(10000):
        grad = gradient(center)
        new_center = [center[i] - lr * grad[i] for i in range(3)]

        old_val = objective(center)
        center = new_center
        new_val = objective(center)

        if new_val >= old_val:
            center = [center[i] - grad[i] * lr * 0.5 for i in range(3)]
            if objective(center) >= old_val:
                break
        lr = lr * 0.95

    return f"{center[0]:.8f} {center[1]:.8f} {center[2]:.8f}"

