def max_passable_width_better(a: float, b: float, l: float) -> float:
    """
    Calculate the maximum width w for coffin of length l through L-shaped corridor.
    This is based on the critical geometric constraint.
    """
    def f(theta):
        """Max width possible at angle theta"""
        return min(a - l * math.sin(theta), b - l * math.cos(theta))

    # Ternary search for the maximum
    low = 0.0001
    high = min(math.pi/2, max(a, b) / max(a, b, 1))

    for _ in range(100):
        m1 = low + (high - low) / 3
        m2 = high - (high - low) / 3
        if f(m1) < f(m2):
            low = m1
        else:
            high = m2

    return f(low)

