        """Calculate the max time all dwarves need to reach point p"""
        max_time = 0
        for dwarf in dwarves:
            # Direct distance from dwarf to point
            direct = manhattan_dist(dwarf, p)

            # Distance via subways
            if subways:
                via_subway = float('inf')
                for subway in subways:
                    total = manhattan_dist(dwarf, subway) + manhattan_dist(subway, p)
                    via_subway = min(via_subway, total)
            else:
                via_subway = float('inf')

            dwarf_time = min(direct, via_subway)
            max_time = max(max_time, dwarf_time)

        return max_time

    # Check all subway stations as potential meeting points
    if subways:
        for subway in subways:
            ans = min(ans, time_to_point(subway))

    # Check Manhattan median as potential meeting point
