    # DFS for cycle detection
    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    order = [1]
    timer = [0]

    def dfs(u):
        visited[u] = True
        parent[u] = order[-1]
        order[-1] = timer[0] + 1
        timer[0] += 1

        for v in adj[u]:
            if not visited[v]:
                parent[v] = u
                dfs(v)
                if order[u] - order[v] + 1 >= k:
                    # Found cycle of sufficient length
                    cycle = []
                    curr = u
                    while True:
                        cycle.append(curr)
                        curr = parent[curr]
                        if curr == v:
                            break
                    cycle.append(v)
                    return f"2\n{k}\n" + " ".join(map(str, cycle))
            elif v != parent[u]:
                # Back edge found - check if it gives a long cycle
                if order[u] - order[v] + 1 >= k:
                    cycle = []
                    curr = u
                    while True:
                        cycle.append(curr)
                        curr = parent[curr]
                        if curr == v:
                            break
                    cycle.append(v)
                    return f"2\n{k}\n" + " ".join(map(str, cycle))

    result = dfs(1)
    if result:
        return result

    # Find independent set
    # Start with vertex 1 if possible, then greedily add non-adjacent vertices
    independent_set = [1]
    selected = {1}

    for v in range(1, n + 1):
        if v in selected:
            continue
        # Check if v is adjacent to any selected vertex
        is_adjacent = False
        for u in independent_set:
            if v in adj[u]:
                is_adjacent = True
                break
        if not is_adjacent:
            independent_set.append(v)
            selected.add(v)
            if len(independent_set) >= k:
                return f"1\n{k}\n" + " ".join(map(str, independent_set))

    return f"1\n{k}\n" + " ".join(map(str, independent_set))

