def rev(num: int) -> int:
    """Reverse a number in decimal system."""
    s = str(num)[::-1].lstrip('0')
    return int(s) if s else 0

def count_lucky_numbers(limit: int) -> int:
    """Count how many numbers in range [1, limit] satisfy rev(x)^2 = x^2."""
    count = 0
    for x in range(1, limit + 1):
        if x * x == (rev(x)) * (rev(x)):
            count += 1
