from functools import reduce
from collections import defaultdict

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd_list(lst):
    if not lst:
        return 0
    return reduce(gcd, lst, lst[0])

def prime_factorization(n):
    """Returns a set of unique prime factors of n"""
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors.add(d)
            temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return factors

def solve(s):
    lines = s.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))
    e = list(map(int, lines[2].split()))

    if n == 0:
        return '0\n'

    initial_gcd = gcd_list(a)
    if initial_gcd == 1:
        return '0\n'

    # Get unique prime factors of the initial GCD
    prime_factors = prime_factorization(initial_gcd)

    if not prime_factors:
        return '0\n'

    # Sort primes by size to process smaller factors first
    sorted_primes = sorted(prime_factors)

    # For each prime, find which judges can help eliminate it
    # A judge i can help eliminate prime p if p divides a[i] and k >= p
    # We need to ensure each prime is handled by at least one selected judge

    min_prices = {}  # prime -> (min_experience, judge_index)

    # Check if k is large enough for smallest prime factor
    if k < sorted_primes[0]:
        return '-1\n'

    # For each prime, find the cheapest judge that can eliminate it
    # A judge i can eliminate p if p | a[i], and p <= k
    for p in sorted_primes:
        if p > k:
            return '-1\n'

        min_exp = float('inf')
        best_judge = -1

        for i in range(n):
            if a[i] % p == 0:
                if e[i] < min_exp:
                    min_exp = e[i]
                    best_judge = i

        if best_judge == -1:
            return '-1\n'

        min_prices[p] = (min_exp, best_judge)

    # Greedy approach: for each prime, select the cheapest judge
    # If a judge can eliminate multiple primes, we count them just once
    selected_judges = set()
    covered_primes = set()

    # Process primes in order, try to eliminate each using cheapest feasible judge
    for p in sorted_primes:
        if p in covered_primes:
            continue

        # Find if any judge not yet selected can help eliminate p
        found = False
        for i in range(n):
            if p in covered_primes:
                continue
            if a[i] % p == 0:
                # Judge i can help eliminate p
                # Check if this judge already helps cover p
                if i not in selected_judges:
                    # Use this judge
                    selected_judges.add(i)
                    covered_primes.add(p)
                    found = True
                    break

        if not found:
            # Need to select a new judge
            best_judge = -1
            min_exp = float('inf')
            for i in range(n):
                if p in covered_primes:
                    continue
                if i in selected_judges:
                    continue
                if a[i] % p == 0:
                    if e[i] < min_exp:
                        min_exp = e[i]
                        best_judge = i

            if best_judge == -1:
                return '-1\n'

            selected_judges.add(best_judge)
            covered_primes.add(p)

    # Calculate total time: number_of_selected_judges * sum_of_experiences
    if not selected_judges:
        return '0\n'

    total_experience = sum(e[i] for i in selected_judges)
    time_spent = len(selected_judges) * total_experience

    return str(time_spent) + '\n'


