def solution(input_str):
    lines = input_str.strip().split('\n')
    n, x0, y0 = int(lines[0].split()[0]), int(lines[0].split()[1]), int(lines[0].split()[2])

    grid = []
    for i in range(1, n + 1):
        grid.append(list(map(int, lines[i].split())))

    # Check if there are any lit cells
    has_lit = any(grid[i][j] == 1 for i in range(n) for j in range(n))
    if not has_lit:
        return "NO"

    actions = []
    visited = set()
    path = []  # Track the path for backtracking

    def can_see(r, c, dr, dc):
        """Check if there's a lit cell in direction (dr, dc) from (r,c)"""
        for k in range(1, n + 1):
            nr, nc = r + dr * k, c + dc * k
            if not (0 <= nr < n and 0 <= nc < n):
                break
            if grid[nr][nc] == 1:
                return True
        return False

    def dfs(r, c):
        """DFS to visit and turn off all lit cells"""
        visited.add((r, c))
        path.append((r, c))

        # Turn off light if present
        if grid[r][c] == 1:
            actions.append('2')

        # Explore neighbors
        for dr, dc, direction, op in [
            (1, 0, 'D', 'U'), (-1, 0, 'U', 'D'),
            (0, 1, 'R', 'L'), (0, -1, 'L', 'R')
        ]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited:
                if can_see(r, c, dr, dc):
                    # Move to neighbor
                    actions.append(direction)
                    dfs(nr, nc)

                    # Turn back to parent
                    actions.append(op)

        if path and path[-1] == (r, c):
            path.pop()

    # Start from x0-1, y0-1 (0-indexed)
    dfs(x0 - 1, y0 - 1)

    return "YES\n" + "".join(actions)

