def is_bitonic(arr):
    if len(arr) <= 1:
        return True
    increasing = True
    decreasing = False
    for i in range(1, len(arr)):
        if arr[i] > arr[i-1] and increasing:
            pass
        elif arr[i] > arr[i-1]:
            decreasing = False
        elif arr[i] < arr[i-1] and not decreasing:
            decreasing = True
        elif arr[i] >= arr[i-1] and decreasing:
            return False
    return True


def format_output(result, n, m):
    return '\n'.join(' '.join(map(str, row)) for row in result)


def construct_bitonic(n, m, elements, row_maxes, col_maxes):
    result = [[0] * m for _ in range(n)]
    used = [False] * (n * m + 1)

    for r in range(n):
        for c in range(m):
            idx = r * m + c
            if idx < len(elements):
                result[r][c] = elements[idx]
                used[elements[idx]] = True

    if is_valid(result, row_maxes, col_maxes):
        return result

    return None


def is_valid(result, row_maxes, col_maxes):
