import math

def solution(input_str: str) -> str:
    """
    Find the largest base b (1 < b < x) where there exists a rotatable number of length n in base b.

    A rotatable number of length n in base b has the property that multiplying it by 1, 2, ..., n
    produces all possible cyclic rotations of the number.

    This property is satisfied when n+1 is prime and b is a primitive root modulo n+1.
    """
    n, x = map(int, input_str.strip().split())

