    # If n+1 is not prime, no solution exists (based on the mathematical structure of these problems)
    if not is_prime(n_plus_1):
        return "-1\n"

    # Try bases from x-1 down to 2 (looking for largest valid base)
    for b in range(x - 1, 1, -1):
        # Check if b is coprime to n_plus_1 (required for primitive root)
        if math.gcd(b, n_plus_1) != 1:
            continue

        # Check if b is primitive root modulo n_plus_1
        # b is primitive root if b^((n_plus_1-1)/q) != 1 mod n_plus_1 for all prime factors q of n_plus_1-1
        if is_primitive_root(b, n_plus_1):
