def is_prime(num) -> bool:
    """Miller-Rabin primality test."""
    if num < 2:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0:
        return False

    # Write num-1 as d * 2^r
    d = num - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1

    # Deterministic bases for num < 10^9
    for a in [2, 7, 61]:
        if a >= num:
            continue
        x = pow(a, d, num)
        if x == 1 or x == num - 1:
            continue
        for _ in range(r - 1):
            x = pow(x, 2, num)
            if x == num - 1:
                break
        else:
            return False

    return True


def get_prime_factors(n) -> list:
    """Get unique prime factors of n."""
    factors = []
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.append(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.append(temp)
    return factors


def is_primitive_root(b, p) -> bool:
    """Check if b is a primitive root modulo prime p."""
    phi = p - 1  # Euler's totient for prime p
    factors = get_prime_factors(phi)

    for q in factors:
        if pow(b, phi // q, p) == 1:
            return False
    return True


