    return len(str(n))

def solve(expr):
    n = len(expr)
    i = 0

    def count_digits_of_val(val):
        if val == 0:
            return 1
        length = 1
        while val >= 10:
            val //= 10
            length += 1
        return length

    def concat_range(l, r):
        """Concatenate numbers from l to r, return value, total_digits"""
        if l > r:
            return 0, 0
        if l == r:
            return l % MOD, count_digits_of_val(l)

        total_digits = 0
        value = 0

        for num in range(l, r + 1):
            d = count_digits_of_val(num)
            total_digits += d
            value = (value * power_mod(10, d)) % MOD
            value = (value + num) % MOD

        return value % MOD, total_digits

    def repeat_expr(repeat_count, inner_result, inner_digits):
        if repeat_count == 0:
            return 0
        if repeat_count == 1:
            return inner_result

        result = inner_result
        for _ in range(2, repeat_count + 1):
            result = (result * power_mod(10, inner_digits)) % MOD
            result = (result + inner_result) % MOD
        return result

    # Parse expression with + as top-level separator
    def eval_expression():
        nonlocal i
        results = []

        while i < n:
            # Handle + operator
            if expr[i] == '+':
                i += 1
                continue

            term_result, term_digits = parse_term()
            results.append((term_result, term_digits))
            i += 1

        # Concatenate all terms
        final_result = 0
        total_digits = 0
        for result, digits in results:
            final_result = (final_result * power_mod(10, digits)) % MOD
            final_result = (final_result + result) % MOD
        return final_result

    def parse_term():
        nonlocal i

        while i < n and expr[i] == '+':
            i += 1

        result = parse_number()
        result = result % MOD

        if i < n and expr[i] == '-':
            i += 1
            if i < n and expr[i].isdigit():
                l, digits_l = parse_number(), 0
                r, digits_r = parse_number(), 0

                if l > r:
                    l, r = r, l

                # Calculate value from comma to end
                range_result, _ = concat_range(l, r)
                return range_result

        if i < n and expr[i] == '(':
            i += 1
            inner_count, digits_count = parse_number(), 0

            inner_result = parse_expression()
            inner_digits, _ = parse_number(), 0

            if i < n and expr[i] == ')':
                i += 1

            return repeat_expr(inner_count, inner_result, inner_digits)

        return result

    def parse_number():
        nonlocal i
        start = i
        while i < n and expr[i].isdigit():
            i += 1

        if start == i:
            return 0
        return int(expr[start:i])

    return eval_expression() % MOD

