    def find(x):
        path = []
        while parent[x] != x:
            path.append(x)
            x = parent[x]
        for node in path:
            parent[node] = x
        return x

    def union(x, y):
        root_x, root_y = find(x), find(y)
        if root_x != root_y:
            parent[root_x] = root_y

    # Connect elements that must be in the same set
    for i, x in enumerate(p):
        target_a = a - x
        target_b = b - x
        if target_a in p_set:
            union(i, p_idx[target_a])
        if target_b in p_set:
            union(i, p_idx[target_b])

    # Group by connected components
    components = {}
    for i in range(n):
        root = find(i)
        if root not in components:
            components[root] = []
        components[root].append(i)

    ans = [0] * n

    # Check each component
    for indices in components.values():
        can_a = True
        can_b = True
        for idx in indices:
            x = p[idx]
            if (a - x) not in p_set:
                can_a = False
            if (b - x) not in p_set:
                can_b = False

        if not can_a and not can_b:
            return "NO"

        for idx in indices:
            ans[idx] = 0 if can_a else 1

    return "YES\n" + " ".join(map(str, ans)) + "\n"

