import sys

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    if not lines:
        return "0"

    n, h, m = map(int, lines[0].split())
    restrictions = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        if len(parts) != 4:
            continue
        l, r, x, c = map(int, parts)
        restrictions.append((l, r, x, c))

    # For small problem sizes, use brute force
    if n <= 15:
        from itertools import product

        best = 0
        for heights in product(range(h + 1), repeat=n):
            gain = sum(height**2 for height in heights)
            fine = 0
            for l, r, x, c in restrictions:
                l_idx, r_idx = l - 1, r
                # Handle case where range might exceed array bounds
                seg_heights = heights[l_idx:r_idx]
                seg_max = max(seg_heights) if seg_heights else 0
                if seg_max > x:
                    fine += c
            best = max(best, gain - fine)
        return str(best)

    # For larger inputs, use min-cut approach
    # This is a known min-cut / max-flow problem

    INF = float('inf')
    source, sink = 0, 1
    num_nodes = 2 + m + m + n * (h + 1)

    class MaxFlow:
        def __init__(self, n):
            self.n = n
            self.graph = [[] for _ in range(n)]

        def add_edge(self, u, v, cap):
            self.graph[u].append([v, cap, len(self.graph[v])])
            self.graph[v].append([u, 0, len(self.graph[u]) - 1])

        def bfs(self, s, t, dist):
            for i in range(self.n):
                dist[i] = -1
            dist[s] = 0
            queue = [s]
            while queue:
                u = queue.pop(0)
                for v, cap, rev in self.graph[u]:
                    if cap > 0 and dist[v] == -1:
                        dist[v] = dist[u] + 1
                        queue.append(v)
            return dist[t] != -1

        def dfs(self, u, t, pushed, dist, ptr):
            if pushed == 0 or u == t:
                return pushed
            for i in range(ptr[u], len(self.graph[u])):
                ptr[u] = i
                v, cap, rev = self.graph[u][i]
                if dist[v] != dist[u] + 1 or cap == 0:
                    continue
                tr = self.dfs(v, t, min(pushed, cap), dist, ptr)
                if tr == 0:
                    continue
                self.graph[u][i][1] -= tr
                self.graph[v][rev][1] += tr
                return tr
            return 0

        def dinic(self, s, t):
            flow = 0
            while True:
                dist = [-1] * self.n
                if not self.bfs(s, t, dist):
                    break
                ptr = [0] * self.n
                while True:
                    tr = self.dfs(s, t, INF, dist, ptr)
                    if tr == 0:
                        break
                    flow += tr
            return flow

    mf = MaxFlow(num_nodes)

    # Build the min-cut graph
    # Source -> restriction nodes (capacity = c_i)
    # If cut = pay fine, else enforce constraints
    # constraint fulfillment requires heights in range to be <= x
    # spot nodes model height choices across levels

    for i, (l, r, x, c) in enumerate(restrictions):
        rnode = 2 + i
        mf.add_edge(source, rnode, c)

    # For each spot and each height threshold, model the choice
    # Spot node (j, k) where k represents height <= k
    # Edges between consecutive height levels
    # Connection from restriction to spot: if satisfied, height <= x
    for i, (l, r, x, c) in enumerate(restrictions):
        rnode = 2 + i
        for j in range(l - 1, r):
            # Spot j must have height <= x if restriction not violated
            # Model this with forbidden higher heights
            # Create spot nodes for each height level for each spot
            for k in range(0, h + 1):
                spot_node = 2 + m + j * (h + 1) + k
                if k > x:
                    # If we don't pay, we can't be at level > x
                    # Connect restriction node to this spot level with INF
                    # This will force cut at earlier level if restriction not violated
                    mf.add_edge(rnode, spot_node, INF)

    # Height level transitions for each spot
    # Transition from height k to k+1 gives (k+1)^2 - k^2 = 2k + 1 gain
    # Model these as capacities to sink
    for j in range(n):
        for k in range(h):
            u = 2 + m + j * (h + 1) + k
            v = 2 + m + j * (h + 1) + (k + 1)
            gain = 2 * k + 1
            if gain > 0:
                mf.add_edge(u, v, gain)

    # Finally reach sink from highest layers
    for j in range(n):
        final = 2 + m + j * (h + 1) + h
        mf.add_edge(final, sink, INF)

    cut = mf.dinic(source, sink)
    return str(cut)

