def solution(input_str):
    """
    Find the minimum number of operations to reduce n to 0 by repeatedly
    subtracting a digit from the number (digit must exist in the number).
    """
    n = int(input_str.strip())

    if n == 0:
        return '0'

    # BFS/Dijkstra to find minimum operations
    # distance[x] = minimum operations to reach 0 from x (or from start to x)
    distance = {n: 0}
    heap = [(0, n)]  # (distance, current_value)

    while heap:
        dist, current = heapq.heappop(heap)

        if current == 0:
            return str(dist)

        current_str = str(current)
        current_digits = set(int(d) for d in current_str)

        for d in current_digits:
            next_val = current - d
            if next_val not in distance:
                distance[next_val] = dist + 1
                heapq.heappush(heap, (dist + 1, next_val))

    return '0'


