        """
        Count valid sequences starting from current_pos with remaining steps to make.
        visited_mask has bit (p-1) set if planet p has been visited.
        """
        if remaining == 0:
            return 1

        state = (remaining, current_pos, visited_mask)
        if state in memo:
            return memo[state]

        total = 0
        # Try all possible next positions: from 1 to current_pos + m
        # Constraint: next_pos must not have been visited
        for next_pos in range(1, min(n + 1, current_pos + m + 1)):
            if not (visited_mask & (1 << (next_pos - 1))):
                total = (total + count_sequences(next_pos, remaining - 1, visited_mask | (1 << (next_pos - 1)))) % MOD

        memo[state] = total
        return total

    # Sum over all possible starting planets
    result = 0
    for start in range(1, n + 1):
        result = (result + count_sequences(start, k - 1, 1 << (start - 1))) % MOD

    return str(result)
